import hmac
import hashlib
import time
import struct
import os
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
MAX_TOKEN_AGE = 300  # 5 minutes

class TokenStore:
    def __init__(self):
        self.revoked_tokens = set()
        self.usage_counter = {}

    def revoke(self, token_id):
        self.revoked_tokens.add(token_id)

    def is_revoked(self, token_id):
        return token_id in self.revoked_tokens

    def record_usage(self, token_id):
        self.usage_counter[token_id] = self.usage_counter.get(token_id, 0) + 1

    def get_usage_count(self, token_id):
        return self.usage_counter.get(token_id, 0)

token_store = TokenStore()

def create_token(user_id, role, max_uses):
    """Create a signed token with embedded permissions."""
    timestamp = int(time.time())
    token_id = os.urandom(8).hex()
    # Pack: token_id (16 hex chars) | user_id | role | max_uses | timestamp
    payload = f"{token_id}|{user_id}|{role}|{max_uses}|{timestamp}"
    signature = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), 
                         payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}|{signature}"

def verify_token(token):
    """Verify token signature and extract claims."""
    parts = token.rsplit('|', 1)
    if len(parts) != 2:
        return None
    payload, provided_sig = parts
    expected_sig = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
                            payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(provided_sig, expected_sig):
        return None
    fields = payload.split('|')
    if len(fields) != 5:
        return None
    return {
        'token_id': fields[0],
        'user_id': fields[1],
        'role': fields[2],
        'max_uses': fields[3],
        'timestamp': fields[4]
    }

def check_token_constraints(claims):
    """Validate token hasn't expired, been revoked, or exceeded usage limits."""
    # Check expiration
    token_time = int(claims['timestamp'])
    if time.time() - token_time > MAX_TOKEN_AGE:
        return False, "Token expired"

    # Check revocation
    if token_store.is_revoked(claims['token_id']):
        return False, "Token revoked"

    # Check usage limits
    max_uses = int(claims['max_uses'])
    current_uses = token_store.get_usage_count(claims['token_id'])

    # A max_uses of -1 means unlimited
    if max_uses != -1 and current_uses >= max_uses:
        return False, "Usage limit exceeded"

    return True, "OK"

def authorize_action(claims, required_role):
    """Check if the token's role is sufficient for the action."""
    role_hierarchy = {'viewer': 0, 'editor': 1, 'admin': 2, 'superadmin': 3}
    token_role_level = role_hierarchy.get(claims['role'], -1)
    required_level = role_hierarchy.get(required_role, 99)
    return token_role_level >= required_level

@app.route('/api/admin/users', methods=['GET'])
def list_users():
    token = request.headers.get('X-Auth-Token', '')
    claims = verify_token(token)
    if not claims:
        abort(401)

    valid, msg = check_token_constraints(claims)
    if not valid:
        abort(403, description=msg)

    if not authorize_action(claims, 'admin'):
        abort(403, description="Insufficient privileges")

    token_store.record_usage(claims['token_id'])
    return jsonify({"users": ["alice", "bob", "charlie"]})

@app.route('/api/data', methods=['GET'])
def get_data():
    token = request.headers.get('X-Auth-Token', '')
    claims = verify_token(token)
    if not claims:
        abort(401)

    valid, msg = check_token_constraints(claims)
    if not valid:
        abort(403, description=msg)

    if not authorize_action(claims, 'viewer'):
        abort(403, description="Insufficient privileges")

    token_store.record_usage(claims['token_id'])
    return jsonify({"data": "sensitive information"})

@app.route('/api/token', methods=['POST'])
def issue_token():
    """Issue a new token. In production, this would require authentication."""
    data = request.get_json()
    user_id = data.get('user_id', 'anonymous')
    role = data.get('role', 'viewer')
    max_uses = data.get('max_uses', 10)

    # Validate role
    allowed_roles = ['viewer', 'editor']
    if role not in allowed_roles:
        abort(403, description="Cannot self-issue privileged tokens")

    # Validate max_uses - must be positive or -1 for unlimited
    if not isinstance(max_uses, int) or (max_uses < 1 and max_uses != -1):
        abort(400, description="Invalid max_uses value")

    token = create_token(user_id, role, max_uses)
    return jsonify({"token": token})

@app.route('/api/admin/promote', methods=['POST'])
def promote_user_token():
    """Admin endpoint to create elevated tokens."""
    token = request.headers.get('X-Auth-Token', '')
    claims = verify_token(token)
    if not claims:
        abort(401)

    valid, msg = check_token_constraints(claims)
    if not valid:
        abort(403, description=msg)

    if not authorize_action(claims, 'superadmin'):
        abort(403, description="Only superadmins can promote")

    data = request.get_json()
    new_role = data.get('role', 'admin')
    user_id = data.get('user_id')
    max_uses = data.get('max_uses', 5)

    new_token = create_token(user_id, new_role, max_uses)
    token_store.record_usage(claims['token_id'])
    return jsonify({"token": new_token})

